-- =============================================================================
-- Hired — Current schema (read-only reflection of all applied migrations).
--
-- DO NOT EDIT THIS FILE DIRECTLY. The source of truth is the ordered migration
-- files under src/db/migrations/. This file is regenerated/kept in sync so a
-- fresh reader can see the whole shape without walking migrations.
--
-- See .kiro/specs/hired/design.md § 5 for rationale behind each decision.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Jobs scraped from Happy Agent (platform.uplers.com) or added via paste-link.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS jobs (
    id                   SERIAL PRIMARY KEY,
    source               VARCHAR(32) NOT NULL,     -- 'happy_agent' | 'paste_link'
    company_name         VARCHAR(255) NOT NULL,
    job_title            VARCHAR(255) NOT NULL,
    job_url              TEXT NOT NULL,            -- LinkedIn / canonical posting URL
    job_description      TEXT,                     -- plain text, paragraphs separated by \n\n
    must_have_skills     TEXT,                     -- comma-separated raw text
    good_to_have_skills  TEXT,
    happy_job_id         VARCHAR(64),              -- Happy's internal id from ?activeJob=
    experience_range     VARCHAR(64),              -- e.g. '2 - 6 Years Exp'
    location_hint        VARCHAR(128),             -- e.g. 'Remote'
    posted_hint          VARCHAR(128),             -- e.g. 'Within 1 day · Be an early applicant'
    created_at           TIMESTAMPTZ DEFAULT now(),
    UNIQUE (job_url)                               -- natural key dedup
);

CREATE INDEX IF NOT EXISTS idx_jobs_happy_job_id ON jobs(happy_job_id);

-- -----------------------------------------------------------------------------
-- Each click of Run Agent on a job creates one `runs` row.
-- `channels` captures what the user picked in the modal.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS runs (
    id                   SERIAL PRIMARY KEY,
    job_id               INT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
    channels             VARCHAR(16) NOT NULL,     -- 'gmail' | 'linkedin' | 'both'
    status               VARCHAR(16) NOT NULL DEFAULT 'IN_PROGRESS',
                                                   -- IN_PROGRESS | COMPLETED | FAILED
    marked_as_interview  BOOLEAN DEFAULT false,
    created_at           TIMESTAMPTZ DEFAULT now(),
    completed_at         TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_runs_job ON runs(job_id);

-- -----------------------------------------------------------------------------
-- Contacts discovered inside a single run. 1-8 per run (user-selected).
-- Status columns are DERIVED from `events` and may be rebuilt by replay.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS contacts (
    id                       SERIAL PRIMARY KEY,
    run_id                   INT NOT NULL REFERENCES runs(id) ON DELETE CASCADE,
    name                     VARCHAR(255) NOT NULL,
    title                    VARCHAR(255),
    tenure_hint              VARCHAR(128),         -- e.g. '2y at Appscrip'
    email                    VARCHAR(255),
    email_verified           BOOLEAN DEFAULT false,
    linkedin_url             TEXT,
    selected_for_gmail       BOOLEAN DEFAULT false,
    selected_for_linkedin    BOOLEAN DEFAULT false,
    gmail_status             VARCHAR(32) DEFAULT 'PENDING',
                                            -- PENDING | QUEUED | SENT | REPLIED | BOUNCED | FAILED
    linkedin_status          VARCHAR(32) DEFAULT 'PENDING',
                                            -- PENDING | CONNECT_DRAFTED | CONNECT_SENT
                                            -- | CONNECTED | DM_DRAFTED | DM_SENT | REPLIED | DECLINED
    gmail_thread_id          VARCHAR(255),
    linkedin_dm_draft        TEXT,                 -- rendered template, ready to send
    discovered_via           VARCHAR(32),          -- which DiscoverySource adapter (D4 telemetry)
    email_found_via          VARCHAR(32),          -- which EmailFinder adapter
    email_verified_via       VARCHAR(32),          -- which EmailVerifier adapter
    intent_label             VARCHAR(255),         -- free-form, from Gemini classification
    sentiment                VARCHAR(16),          -- POSITIVE | NEGATIVE
    created_at               TIMESTAMPTZ DEFAULT now(),
    last_activity            TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_contacts_run ON contacts(run_id);
CREATE INDEX IF NOT EXISTS idx_contacts_gmail_thread ON contacts(gmail_thread_id);
CREATE INDEX IF NOT EXISTS idx_contacts_linkedin_status ON contacts(linkedin_status);

-- -----------------------------------------------------------------------------
-- Append-only event log. Never UPDATE, never DELETE. (D3)
-- Source of truth; status columns on `contacts` are caches reconstructable
-- by replaying events for a given contact_id in created_at order.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS events (
    id          BIGSERIAL PRIMARY KEY,
    contact_id  INT NOT NULL REFERENCES contacts(id) ON DELETE CASCADE,
    event_type  VARCHAR(64) NOT NULL,
    payload     JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at  TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_events_contact ON events(contact_id);
CREATE INDEX IF NOT EXISTS idx_events_type_time ON events(event_type, created_at);

-- -----------------------------------------------------------------------------
-- Daily cap enforcement (D6). One row per day, incremented atomically.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS daily_logs (
    run_date    DATE PRIMARY KEY DEFAULT CURRENT_DATE,
    runs_count  INT DEFAULT 0
);

-- -----------------------------------------------------------------------------
-- Credit telemetry for the three pluggable providers (D4).
-- Dashboard reads this to show "N/M used this month" per adapter.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS provider_credits (
    provider_name       VARCHAR(64) PRIMARY KEY,
    provider_kind       VARCHAR(32) NOT NULL,    -- 'discovery' | 'email_finder' | 'email_verifier'
    free_quota_monthly  INT,                      -- NULL if unlimited or unknown
    estimated_used      INT DEFAULT 0,
    last_reset          DATE DEFAULT (date_trunc('month', now()))::DATE,
    last_call_at        TIMESTAMPTZ
);
